// --- Mapeadores: linha do Supabase (snake_case) -> forma usada na UI ---
function mapDbCatalogo(row) {
  return { id: row.id, marca: row.marca, modelo: row.modelo, escala: row.escala, ano: row.ano ?? '', fabricante: row.fabricante || '', tema: row.tema, valorCompra: Number(row.valor_compra) || 0, valorEstimado: Number(row.valor_estimado) || 0 };
}
function mapDbWishlist(row) {
  return { id: row.id, marca: row.marca, modelo: row.modelo, escala: row.escala, tema: row.tema, prioridade: row.prioridade, valorEstimado: Number(row.valor_estimado) || 0 };
}
function mapDbPedido(row) {
  return { id: row.id, tipo: row.tipo, peca: row.peca, contraparte: row.contraparte, valor: Number(row.valor) || 0, status: row.status, data: row.data };
}
function mapDbCliente(row) {
  return { id: row.id, nome: row.nome, email: row.email, plano: row.plano, status: row.status, inicio: row.inicio, valorPago: Number(row.valor_pago) || 0 };
}
function mapDbGaleria(row) {
  return { id: row.id, titulo: row.titulo, local: row.local || '', tema: row.tema || null, fotoUrl: row.foto_url || null };
}

