function liveryFor(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) hash = str.charCodeAt(i) + ((hash << 5) - hash);
  return LIVERY[Math.abs(hash) % LIVERY.length];
}
function code(id) { return `156A·${String(id).padStart(3, '0')}`; }

function normKey(k) {
  return String(k).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
}

const COLUMN_ALIASES = {
  marca: ['marca', 'brand'],
  modelo: ['modelo', 'model'],
  escala: ['escala', 'scale'],
  ano: ['ano', 'year'],
  fabricante: ['fabricante', 'manufacturer', 'fabricantediecast'],
  tema: ['tema', 'theme', 'categoria'],
  valorCompra: ['valordecompra', 'valorcompra', 'precocompra', 'compra', 'purchaseprice'],
  valorEstimado: ['valorestimado', 'valorestimativa', 'estimado', 'estimatedvalue'],
};

function mapRowToCatalogItem(row) {
  const normalized = {};
  Object.keys(row).forEach(k => { normalized[normKey(k)] = row[k]; });
  const item = {};
  Object.entries(COLUMN_ALIASES).forEach(([field, aliases]) => {
    for (const alias of aliases) {
      if (normalized[alias] !== undefined && normalized[alias] !== '') { item[field] = normalized[alias]; break; }
    }
  });
  return item;
}

